args.command:
perl -e '
use strict;
use warnings;
use File::Find;
use File::Basename;

my $root = "/bench/repo";
my $internal = "$root/internal";

my @decls;
find(sub {
    return unless /\.go$/;
    my $path = $File::Find::name;
    my $rel = $path;
    $rel =~ s/^\Q$root\E\///;
    open my $fh, "<", $path or die $!;
    my $content = do { local $/; <$fh> };
    close $fh;
    my $pkg = "?";
    if ($content =~ /^package\s+(\w+)/m) { $pkg = $1; }
    while ($content =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/mg) {
        my ($recv, $name) = ($1, $2);
        my $pos = $-[0];
        my $line_start = rindex($content, "\n", $pos-1) + 1;
        my $line_end = index($content, "\n", $pos);
        my $line = substr($content, $line_start, $line_end - $line_start);
        next if $line =~ /^\s*\/\//;
        my $is_test = ($path =~ /_test\.go$/);
        push @decls, [$name, $recv // "", $rel, $pkg, $is_test];
    }
}, $internal);

print "Total declarations: " . scalar(@decls) . "\n";
print "Non-test: " . scalar(grep { !$_->[4] } @decls) . "\n\n";
print "All non-test decls:\n";
for my $d (grep { !$_->[4] } @decls) {
    my $recv = $d->[1] ? "($d->[1]) " : "";
    print "$recv$d->[0]  $d->[2]  pkg=$d->[3]\n";
}
'

